code='''from dataclasses import dataclass

@dataclass
class State:
    original: list
    left: tuple
    right: tuple
    ticks: int = 0


def init(board):
    marks=[]
    for r in range(11):
        for c in range(11):
            if board[6+5*r][6+5*c]==10:
                marks.append((r,c))
    marks.sort(key=lambda p:p[1])
    return State([row[:] for row in board],marks[0],marks[1],0)


def _walk(state,p):
    r,c=p
    return 0<=r<11 and 0<=c<11 and state.original[6+5*r][6+5*c] in (5,10)


def step(state,action):
    a=action[0]
    l,r=state.left,state.right
    if a in (1,2,3,4):
        dl={1:(-1,0),2:(1,0),3:(0,-1),4:(0,1)}[a]
        dr={1:(-1,0),2:(1,0),3:(0,1),4:(0,-1)}[a]
        nl=(l[0]+dl[0],l[1]+dl[1]); nr=(r[0]+dr[0],r[1]+dr[1])
        if _walk(state,nl): l=nl
        if _walk(state,nr): r=nr
    return State(state.original,l,r,state.ticks+1)


def render(state):
    b=[row[:] for row in state.original]
    for r in range(11):
        for c in range(11):
            if b[6+5*r][6+5*c]==10:
                for y in range(4+5*r,9+5*r):
                    for x in range(4+5*c,9+5*c): b[y][x]=5
    for r,c in {state.left,state.right}:
        for y in range(4+5*r,9+5*r):
            for x in range(4+5*c,9+5*c): b[y][x]=10
    # The two lower corners are cleared alternately toward the upper corners.
    perimeter=[(63-x,0) for x in range(64)]+[(0,x) for x in range(1,64)]+[(x,63) for x in range(1,64)]+[(63,x) for x in range(62,0,-1)]
    # Actual order interleaves left bottom-up and right top-down.
    order=[]
    for i in range(63):
        order.extend([(63-i,0),(i,63)])
    order.extend([(0,x) for x in range(63,0,-1)])
    order.extend([(63,x) for x in range(1,64)])
    for y,x in order[:state.ticks]: b[y][x]=0
    return b


def won(state):
